# Code generated by Claude
"""
A slide-ready version of data/elbow_snap/j4_sweeps.png for people who have not seen the project.

    source .venv/bin/activate
    python experiments/elbow_snap_readable.py        # writes data/elbow_snap/elbow_snap_readable.png

Re-runs the joint-4 sweeps of experiments/elbow_snap_sweep.py for the left arm with the
wristB wrist (joints 5-7 = -0.6, -0.4, -0.9 rad) in five poses, plus the sweep back up for
"down to the side", and the same sweeps with the safety filter OFF (to check the footnote).
Headless, kinematic; no viewer, no MuJoCo.
"""

import argparse
import sys
import textwrap
from pathlib import Path

import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from experiments.elbow_snap_sweep import (J4_START, J4_STEP, POSES, WRIST_VARIANTS,  # noqa: E402
                                          find_snap, j4_values_down, joints_for_direction,
                                          run_sweep)
from src.safety_filter import SafetyFilter  # noqa: E402

ARM = "left"
WRIST = WRIST_VARIANTS["wristB"]
PANELS = [("forward at shoulder height", "Reaching forward"),
          ("forward and down to bench", "Reaching forward and down"),
          ("down to the side", "Down to the side"),
          ("hanging at rest", "Hanging at rest"),
          ("reaching up", "Reaching up")]
HYSTERESIS_POSE = "down to the side"
deg = np.degrees


def compute():
    import openarm_teleop
    spec = np.load(Path(openarm_teleop.__file__).parent / "assets/specs/openarm_v1.npz")
    limits = (spec[f"{ARM}_arm/joint_lower"], spec[f"{ARM}_arm/joint_upper"])
    on, off = SafetyFilter(True), SafetyFilter(False)
    directions = {p[0]: p[1] for p in POSES}
    down, up_vals = j4_values_down(), np.round(np.arange(0.0, J4_START + 1e-9, J4_STEP), 6)
    data = {}
    for pose, _ in PANELS:
        j1, j2, j3, _ = joints_for_direction(on, ARM, directions[pose], limits)
        q = np.array([j1, j2, j3, np.nan, *WRIST])
        res = run_sweep(on, ARM, q, down)
        d = dict(q=q, res=res, snap=find_snap(res))
        r_off = run_sweep(off, ARM, q, down)
        d["off_diff"] = float(np.abs(r_off["out"] - res["out"]).max())            # all 7 joints
        d["off_diff_j4"] = float(np.abs(r_off["out"][:, 3] - res["out"][:, 3]).max())
        d["off_snap"] = find_snap(r_off)
        if pose == HYSTERESIS_POSE:
            d["up"] = run_sweep(on, ARM, q, up_vals, q_start=res["out"][-1], reset=False)
            d["up_off_diff"] = float(np.abs(run_sweep(off, ARM, q, up_vals, q_start=res["out"][-1],
                                                      reset=False)["out"][:, 3] - d["up"]["out"][:, 3]).max())
        data[pose] = d
    return data


def plot(data, path):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.ticker import FuncFormatter

    INK, INK2, GRID, SURFACE = "#0b0b0b", "#3d3c39", "#e4e3df", "#fcfcfb"
    BLUE, ORANGE, GREY, WRONG = "#2a78d6", "#eb6834", "#7a7974", "#d6455d"
    fig, axes = plt.subplots(2, 3, figsize=(18, 12.2), facecolor=SURFACE)
    axes = axes.ravel()
    top = deg(J4_START)
    for ax, (pose, title) in zip(axes, PANELS + [(HYSTERESIS_POSE, None)]):
        d = data[pose]
        r, s = d["res"], d["snap"]
        x, y = deg(r["j4_cmd"]), deg(r["out"][:, 3])
        hyst = title is None
        ax.plot([top, 0], [top, 0], color=GREY, lw=2.2, ls=":", label="Correct (returned = sent)")
        if not hyst:
            ax.fill_between(x[x <= deg(s["j4_cmd"]) + 1e-9], x[x <= deg(s["j4_cmd"]) + 1e-9],
                            y[x <= deg(s["j4_cmd"]) + 1e-9], color=WRONG, alpha=0.16, lw=0,
                            label="Output is wrong")
            ax.plot(x, y, color=BLUE, lw=3.4, label="Actual output")
        else:
            ax.plot(x, y, color=BLUE, lw=4.6, label="straightening")
            ax.plot(deg(d["up"]["j4_cmd"]), deg(d["up"]["out"][:, 3]), color=ORANGE, lw=2.2,
                    ls=(0, (5, 3)), label="bending back")
        ax.plot([deg(s["j4_cmd"])], [deg(s["j4_out"])], "o", color=INK, ms=9, zorder=5)
        text = (f"Snap at {deg(s['j4_cmd']):.0f}°: elbow\njumps to {deg(s['j4_out']):.1f}°, hand ends\n"
                f"up {s['werr_after'] / 10:.0f} cm off target") if not hyst else \
            f"Snaps at {deg(s['j4_cmd']):.0f}°\nin both directions"
        ax.annotate(text, xy=(deg(s["j4_cmd"]), deg(s["j4_out"])), xytext=(0.03, 0.07),
                    textcoords="axes fraction", color=INK, fontsize=14, va="bottom",
                    bbox=dict(boxstyle="round,pad=0.35", fc=SURFACE, ec="#b9b8b2", lw=1),
                    arrowprops=dict(arrowstyle="-|>", color=INK, lw=1.6, shrinkA=0, shrinkB=6))
        ax.set_title(title if not hyst else "\n".join(textwrap.wrap(
            "Straightening, then bending back: it snaps at the same point both ways", 31)),
            color=INK, fontsize=17, fontweight="bold", loc="left", pad=10)
        ax.set_xlabel("Elbow bend sent to solve()", color=INK, fontsize=15, labelpad=8)
        ax.set_ylabel("Elbow bend returned by solve()", color=INK, fontsize=15, labelpad=8)
        ax.set_xlim(top + 1.5, -1.5)                         # bent on the left, straight on the right
        ax.set_ylim(-1.5, top + 1.5)
        ticks = [0, 10, 20, 30]
        for axis in (ax.xaxis, ax.yaxis):
            axis.set_ticks(ticks)
            axis.set_major_formatter(FuncFormatter(lambda v, _: f"{v:.0f}°"))
        ax.set_facecolor(SURFACE)
        ax.grid(color=GRID, lw=1)
        ax.tick_params(colors=INK2, labelsize=14)
        for side in ("top", "right"):
            ax.spines[side].set_visible(False)
        for side in ("left", "bottom"):
            ax.spines[side].set_color("#b9b8b2")
        ax.legend(loc="upper right", frameon=False, fontsize=13, labelcolor=INK2)
        ax.annotate("", xy=(0.80, -0.27), xytext=(0.20, -0.27), xycoords="axes fraction",
                    annotation_clip=False, arrowprops=dict(arrowstyle="-|>", color=INK2, lw=2))
        ax.text(0.5, -0.27, " elbow straightening ", transform=ax.transAxes, ha="center",
                va="center", fontsize=13, color=INK2, backgroundcolor=SURFACE)
    w = ", ".join(f"{deg(v):.0f}°" for v in WRIST)
    fig.suptitle("solve() suddenly straightens the elbow when it is almost straight", color=INK,
                 fontsize=29, fontweight="bold", x=0.015, y=0.985, ha="left")
    fig.text(0.015, 0.905, "Each panel: the left arm is held in one pose while the elbow is slowly "
             f"straightened. The wrist is turned (joints 5-7 = {w}).", color=INK2, fontsize=17, ha="left")
    fig.text(0.015, 0.012, "Same result with the safety filter on or off.", color=INK, fontsize=17,
             ha="left", va="bottom")
    fig.subplots_adjust(left=0.06, right=0.985, top=0.83, bottom=0.115, wspace=0.27, hspace=0.78)
    fig.savefig(path, dpi=110, facecolor=SURFACE)


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--out", default="data/elbow_snap/elbow_snap_readable.png")
    args = ap.parse_args()
    data = compute()
    for pose, title in PANELS:
        d = data[pose]
        s = d["snap"]
        print(f"{title:28s} joints 1-3 {np.round(d['q'][:3], 3)}  snap at {deg(s['j4_cmd']):.2f} deg "
              f"({s['j4_cmd']:.3f} rad), output {deg(s['j4_out']):.2f} deg, wrist error {s['werr_after']:.1f} mm; "
              f"filter OFF: elbow output differs by max {d['off_diff_j4']:.1e} rad, snap at "
              f"{deg(d['off_snap']['j4_cmd']):.2f} deg (all 7 joints: max {d['off_diff']:.1e} rad)")
    d = data[HYSTERESIS_POSE]
    up = d["up"]
    err = np.abs(up["out"] - up["cmd"]).max(axis=1)
    back = up["j4_cmd"][np.where(err < 1e-3)[0][0]]
    print(f"Bending back ({HYSTERESIS_POSE}): output returns to the command at {deg(back):.2f} deg "
          f"({back:.3f} rad) vs snap on the way down at {deg(d['snap']['j4_cmd']):.2f} deg; "
          f"filter OFF elbow output differs by max {d['up_off_diff']:.1e} rad")
    out = PROJECT_ROOT / args.out
    out.parent.mkdir(parents=True, exist_ok=True)
    plot(data, out)
    print(f"Saved {out}")


if __name__ == "__main__":
    main()
